//! Sources a person would write in Rules and Actors, including shapes the printer never emits:
//! continuation lines, a user declared late, repeated headings, empty `in`, words that are also
//! keywords. The corpus files of Rules and Actors are generated by `convert`; these are not.

use crate::canonical;
use themis::dsl::{Language, convert, parse};

fn read(name: &str, text: &str) -> themis::dsl::Parsed {
    parse(name, text).unwrap_or_else(|errors| panic!("{name} must parse:\n{errors}\n{text}"))
}

fn first_error(text: &str) -> (u32, u32, String) {
    let errors = parse("bad.themis", text).expect_err("the source is wrong");
    let first = errors.into_iter().next().expect("one error");
    let at = first.location.clone().expect("an error with a position");
    (at.line, at.column, first.to_string())
}

/// Reads `text`, prints it back in every type and reads each print: same JSON each time.
fn same_json_everywhere(name: &str, text: &str) -> serde_json::Value {
    let json = canonical(&read(name, text).policy);
    for to in [Language::Blocks, Language::Rules, Language::Actors] {
        let out = convert(text, to).unwrap_or_else(|error| panic!("{name} to {to}: {error}"));
        assert_eq!(canonical(&read(name, &out).policy), json, "{name} to {to}:\n{out}");
    }
    json
}

const RULES_CONTINUED: &str = "language rules

kinds doc, org

permission doc.read on doc
    label \"Read\"
    // between the continuation lines
    about \"Open the document\"
permission doc.edit on doc needs doc.read  // inline on the first line
    label \"Edit\"  // inline on a continuation line

role editor

g-read: allow role editor to doc.read on doc
    in org:acme
    from 2026-01-01
";

#[test]
fn a_rules_statement_continues_on_more_indented_lines_with_comments_between() {
    let json = same_json_everywhere("continued", RULES_CONTINUED);
    let permissions = json["catalog"]["permissions"].as_array().expect("permissions");
    let read = permissions.iter().find(|p| p["key"] == "doc.read").expect("doc.read");
    assert_eq!(read["label"], "Read");
    assert_eq!(read["description"], "Open the document");
    assert_eq!(json["grants"][0]["scope"]["id"], "acme");
    assert_eq!(json["notes"].as_array().expect("notes").len(), 3);
}

#[test]
fn a_long_permission_is_printed_on_continuation_lines_and_reads_back() {
    let long = format!(
        "language rules\n\nkinds doc\n\npermission doc.read on doc label \"{}\" about \"{}\" non-delegable\n",
        "l".repeat(40),
        "a".repeat(60)
    );
    let out = convert(&long, Language::Rules).expect("convert");
    assert!(out.lines().all(|l| l.chars().count() <= 100), "{out}");
    assert!(out.contains("\n    label"), "{out}");
    assert_eq!(canonical(&read("a", &long).policy), canonical(&read("b", &out).policy));
}

#[test]
fn rules_words_that_are_also_keywords_still_name_things() {
    let text = "language rules

kinds doc, org

permission doc.read on doc

role inherits
role catalog inherits inherits
user:ana has role catalog
user:user has role inherits

user: allow role catalog to doc.read on doc
allow: allow role inherits to doc.read on doc
";
    let json = same_json_everywhere("keywords", text);
    let grants = json["grants"].as_array().expect("grants");
    let ids: Vec<_> = grants.iter().map(|g| g["id"].as_str().expect("id")).collect();
    assert_eq!(ids, ["user", "allow"]);
}

#[test]
fn deny_before_allow_under_first_applicable_keeps_the_order_of_the_grants() {
    let text = "language rules

strategy first_applicable
kinds doc
permission doc.read on doc
role r

g-deny: deny role r to doc.read on doc
g-allow: allow role r to doc.read on doc
";
    let json = same_json_everywhere("order", text);
    assert_eq!(json["strategy"], "first_applicable");
    assert_eq!(json["grants"][0]["id"], "g-deny");
    assert_eq!(json["grants"][1]["id"], "g-allow");
}

const ACTORS_LATE: &str = "language actors

role editor

user ana
  allow doc.read on doc as g-first
  role editor

role editor
  allow doc.read on doc as g-second

user ana
  allow doc.read on doc as g-third

catalog
  kinds doc
  doc.read on doc
";

#[test]
fn an_actors_user_is_declared_on_its_first_declaration_line_wherever_it_sits() {
    let json = same_json_everywhere("late", ACTORS_LATE);
    assert_eq!(json["subjects"].as_array().expect("subjects").len(), 1);
    assert_eq!(json["grants"].as_array().expect("grants").len(), 3);
}

#[test]
fn an_actors_heading_that_only_names_a_declared_role_adds_rules_to_it() {
    let json = same_json_everywhere("repeated", ACTORS_LATE);
    assert_eq!(json["roles"].as_array().expect("roles").len(), 1);
}

#[test]
fn an_actors_in_line_without_rules_under_it_is_an_error_at_its_position() {
    let text = "language actors

role editor
  in org:acme
  allow doc.read on doc as g1
";
    let (line, column, message) = first_error(text);
    assert_eq!((line, column), (4, 3), "{message}");
}

#[test]
fn an_actors_role_heading_one_slip_from_a_declared_role_is_an_error_with_a_suggestion() {
    let text = "language actors

role editor

role editr
  allow doc.read on doc as g1
";
    let (line, column, message) = first_error(text);
    assert_eq!((line, column), (5, 6), "{message}");
    assert!(message.contains("editor"), "{message}");
}

#[test]
fn an_actors_role_heading_with_a_bare_inherits_declares_a_role_close_to_another() {
    let text = "language actors

role editor

role editr inherits
  allow doc.read on doc as g1

catalog
  kinds doc
  doc.read on doc
";
    let json = same_json_everywhere("declared", text);
    assert_eq!(json["roles"].as_array().expect("roles").len(), 2);
}

#[test]
fn a_role_line_under_a_role_heading_says_where_role_lines_belong() {
    let text = "language actors

role editor
  role viewer
";
    let (line, column, message) = first_error(text);
    assert_eq!((line, column), (4, 3), "{message}");
    assert!(message.contains("belong under a user or subject heading"), "{message}");
}

#[test]
fn a_tab_in_the_indentation_is_an_error_in_rules_and_actors() {
    for text in [
        "language actors\n\nrole editor\n\tallow doc.read on doc as g1\n",
        "language rules\n\nkinds doc\npermission doc.read on doc\n\tlabel \"x\"\n",
    ] {
        let (line, _, message) = first_error(text);
        assert!(line >= 4, "{message}");
        assert!(message.contains("tab"), "{message}");
    }
}

#[test]
fn a_non_breaking_space_in_the_indentation_is_an_error_in_rules_and_actors() {
    let text = "language actors\n\nrole editor\n\u{a0}\u{a0}allow doc.read on doc as g1\n";
    let (line, _, message) = first_error(text);
    assert_eq!(line, 4, "{message}");
}

#[test]
fn an_override_resource_owner_takes_a_word_in_rules_and_actors() {
    let rules = "language rules

kinds doc
permission doc.read on doc
override resource-owner owner except doc.read
";
    same_json_everywhere("override", rules);
}
